"""Writes figures/captions.md. Every count is read from saved results (nothing typed in): python -I figures/write_captions.py"""
import sys
sys.path.insert(0, "figures")
import pandas as pd
from common import P2, P3, P4, TASKS, load

M = load(P2 + "metrics.json"); D = load(P4 + "price_of_recall.json"); X3 = load(P3 + "cascade.json")
g = pd.read_parquet(P2 + "groups.parquet")
oof = pd.read_parquet(P3 + "cascade_oof_rep0.parquet")
n_boot = M["n_boot"]; seeds = M["seeds"]
mt = {t: M["metrics"][f"group_{t}"] for t in TASKS}; mr = {t: M["metrics"][f"random_{t}"] for t in TASKS}
test_txt = ", ".join(f"{t} {mt[t]['n_test']} MOFs in {mt[t]['n_test_groups']} groups" for t in TASKS)
rand_txt = ", ".join(f"{t} {mr[t]['n_test']}" for t in TASKS)
cal = {}
for t in TASKS:
    p = pd.read_parquet(P2 + f"pred_group_{t}_s0.parquet"); cal[t] = (int((p.split == "cal").sum()), p[p.split == "cal"].group_id.nunique())
cal_txt = ", ".join(f"{t} {cal[t][0]} MOFs in {cal[t][1]} groups" for t in TASKS)
nlab, nstab, ngr = len(oof), int(oof.all_stable.sum()), oof.group_id.nunique()
reps, K = len(X3["results"]), X3["K"]
pool = ", ".join(f"{t} {D['real']['phase3_' + t]['n']} MOFs in {D['real']['phase3_' + t]['n_groups']} groups" for t in TASKS)
total_m, total_g = len(g), g.group_id.nunique()
split_txt = (f"Splits: {total_m:,} MOFs (union of the three stability tables) in {total_g:,} proxy groups (connected components over 4-letter CSD refcode family and DOI; "
             f"no MOFid is available in the released data), each group wholly in one of train / validation / calibration / test (60/20/20 by MOF count, split seed 0).")

txt = f"""# Draft figure captions

Generated by `figures/write_captions.py` from saved results (`data/processed/phase2..4/`); regenerate with `python -I figures/write_captions.py`.
Files: `figN_*.pdf` is the double-column version (17.5 cm wide), `figN_*_1col.pdf` the single-column version (8.5 cm wide); same content, panels stacked in the single-column version.
Common to all figures: {split_txt} Groups are proxies, so near-duplicate MOFs in different groups may remain across splits. Labels are the released labels.
Stage names: thermal = decomposition temperature >= 350 °C, solvent = solvent-removal (activation) stable, water = water stable (class 2 or 3); 'truly stable' = stable by these released labels.

## Figure 1 (`fig1_group_vs_random`)
**Group-aware splitting lowers the measured performance of the stability models.** Test performance of the released model architectures retrained on a random (MOF-level, grey squares) or a group-aware (orange circles) 60/20/20 split with identical sizes and code (Phase 2 models, training seed 0). (a) AUC for the 'truly stable' call; (b) accuracy of the stable / not-stable call; (c) thermal mean absolute error (°C). Test sets: group-aware {test_txt}; random-split test MOFs: {rand_txt}. Error bars are 95% percentile bootstrap intervals ({n_boot} resamples) over test groups for the group-aware split and over individual MOFs for the random split (the two kinds of interval are not directly comparable). The group-aware test sets differ from the random ones, so differences are indicative only; one split, one seed.

## Figure 2 (`fig2_recall_vs_target`)
**Realised recall of the per-stage conformal threshold.** Realised recall on the group-aware test set against the target recall 1 − α, for the thermal (a), solvent (b) and water (c) stages; grey squares: Phase 2 models (released hyperparameters), orange circles: Phase 3 models (tree-model candidates chosen by group cross-validation on the training groups only); dashed line: target. Thresholds are the k-th smallest calibration-positive score, k = floor(α (n+1)), from the group-aware calibration set ({cal_txt}) and applied to the test sets ({test_txt}). Shaded bands are 95% percentile bootstrap intervals ({n_boot} resamples) over test groups with the threshold held fixed; they show test-set sampling noise only, not the variability of the calibration draw. Each point is one calibration draw (split seed 0), so single points can lie below the diagonal even though the guarantee is for the average over draws.

## Figure 3 (`fig3_kept_vs_recall`)
**Fraction of MOFs kept at each target recall.** Share of all group-aware test MOFs that pass the conformal threshold of each stage (thermal a, solvent b, water c) against the target recall; same models, thresholds and test sets as Fig. 2 (test sets: {test_txt}). Dotted line: a filter without information (kept = recall). Shaded bands: 95% percentile bootstrap intervals ({n_boot} resamples) over test groups, threshold fixed. Lower is better at equal realised recall, but the two model sets have different realised recalls at the same target, so compare them at equal realised recall (see Fig. 2).

## Figure 4 (`fig4_cascade`)
**Stacked thermal, solvent and water filters (cascade) on the MOFs with all three labels.** (a) Recall on the {nstab} MOFs that are stable at all three stages, against the target recall 1 − α. (b) Fraction of the {nlab} MOFs carrying all three labels ({ngr} proxy groups) that pass all three filters. Orange circles: Phase 3 models with the union bound (each stage calibrated at α/3); grey squares: Phase 2 models with the union bound; green triangles: Phase 3 models without the union bound (each stage at α). Scores and thresholds are out-of-fold: groups are split into K = {K} folds, three stages are trained and calibrated on the other folds' groups, and the procedure is repeated for {reps} fold assignments (small dots in (a)); markers are means over the repetitions. Error bars are 95% Clopper-Pearson intervals for the rounded mean count of passes out of {nstab} and do **not** account for the repetitions, which re-use the same MOFs and are not independent. With only {nstab} positives the intervals are wide: the data are consistent with the guarantee but cannot confirm it. Phase 3 configurations were chosen on the training groups of the single split, which gives a small selection leak into these folds. The {nstab} all-stable MOFs are those with thermal >= 350 \u00b0C, solvent label +1 and water class 2 or 3 (a different cut-off gives 3-49). The union bound is **not proved** for this population: each stage's guarantee covers that stage's own stable MOFs, and the all-stable MOFs score lower than the other stage-stable MOFs for thermal and water.

## Figure 5 (`fig5_price_of_recall`)
**The price of recall: fraction of MOFs kept against discriminative power (AUC).** For each stage (thermal a, solvent b, water c) and target recall 0.80 / 0.90 / 0.95 (colours), the fraction of all MOFs that must be kept so that this fraction of the truly stable MOFs is kept, with the threshold known exactly (isolating discrimination from calibration noise). Lines: analytic binormal model at the stage's prevalence. Small squares: **simulated** scores (negatives N(0,1), positives N(d,1)) on each stage's real labels and group ids, one dataset per AUC value, plotted at the sample AUC; they are not measured. Open squares and filled circles: **real** Phase 2 and Phase 3 stage models. Real and synthetic points use the pooled group-aware calibration and test MOFs ({pool}), seed-0 models. Bars are 95% percentile bootstrap intervals ({n_boot} resamples) over groups (both axes for the real models). Simulated scores are independent of group, which is optimistic, and real score distributions need not be binormal.
"""
open("figures/captions.md", "w").write(txt)
print(txt)
